def build_patterns(view_overrides=None):
    overrides = view_overrides or {}
    seen = {}
    patterns = []
    for method, dpath, view, name in ROUTES:
        v = overrides.get(name, view)
        if method in ('post', 'put', 'patch', 'delete', 'any', 'match'):
            v = csrf_exempt(v)
        # Django path matches all methods; the same dpath used by GET+POST
        # only needs one URLconf entry. We dedupe by (dpath, name).
        key = (dpath, name)
        if key in seen:
            continue
        seen[key] = True
        patterns.append(path(dpath, v, name=name))
    return patterns
